 union all select 'migration-ledger:'||m.version,pg_catalog.concat_ws('|',m.name,pg_catalog.md5(m.statements::text),m.created_by) from supabase_migrations.schema_migrations m
 union all select 'relation:'||c.oid::pg_catalog.regclass::text,pg_catalog.concat_ws('|',c.relkind,pg_catalog.pg_get_userbyid(c.relowner),c.relrowsecurity,c.relforcerowsecurity,c.relacl) from pg_catalog.pg_class c where c.oid in(select oid from selected_relations)
 union all select 'column:'||a.attrelid::pg_catalog.regclass::text||'.'||a.attnum,pg_catalog.concat_ws('|',a.attname,pg_catalog.format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attacl,pg_catalog.pg_get_expr(d.adbin,d.adrelid)) from pg_catalog.pg_attribute a left join pg_catalog.pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid in(select oid from selected_relations) and a.attnum>0 and not a.attisdropped
 union all select 'constraint:'||c.conrelid::pg_catalog.regclass::text||'.'||c.conname,pg_catalog.pg_get_constraintdef(c.oid) from pg_catalog.pg_constraint c where c.conrelid in(select oid from selected_relations)
 union all select 'index:'||i.indexrelid::pg_catalog.regclass::text,pg_catalog.pg_get_indexdef(i.indexrelid) from pg_catalog.pg_index i where i.indrelid in(select oid from selected_relations)
 union all select 'trigger:'||t.tgrelid::pg_catalog.regclass::text||'.'||t.tgname,pg_catalog.concat_ws('|',t.tgenabled,pg_catalog.pg_get_triggerdef(t.oid)) from pg_catalog.pg_trigger t where t.tgrelid in(select oid from selected_relations) and not t.tgisinternal
 union all select 'policy:'||p.polrelid::pg_catalog.regclass::text||'.'||p.polname,pg_catalog.concat_ws('|',p.polcmd,p.polpermissive,p.polroles,pg_catalog.pg_get_expr(p.polqual,p.polrelid),pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid)) from pg_catalog.pg_policy p where p.polrelid in(select oid from selected_relations)
)
select pg_catalog.md5(coalesce(pg_catalog.string_agg(signature||'|'||value,E'\n' order by signature),'')) as fingerprint from metadata;
